//! Our own procedural fallback textures (`docs/legal.md` rule 3).
//!
//! Every texture is generated from its key by deterministic code in this file,
//! so the game and all tests work without any third-party image file. License:
//! the same as the repository (generated by our code, no external input).
//!
//! The key of a block texture is the path part of the block's fallback name,
//! e.g. `stone` for `core:fallback/stone`. Unknown keys get a magenta/black
//! "missing texture" checkerboard.

use crate::image::Rgba8Image;

/// Edge length of fallback textures.
pub const FALLBACK_SIZE: u32 = 16;

/// Keys with a dedicated look. Everything else falls back to the missing pattern.
pub const FALLBACK_KEYS: [&str; 21] = [
    "stone",
    "dirt",
    "grass_block",
    "sand",
    "gravel",
    "oak_log",
    "oak_planks",
    "coal_ore",
    "iron_ore",
    "cobblestone",
    "water",
    "oak_leaves",
    "glass",
    "torch",
    "glowstone",
    "spruce_log",
    "spruce_leaves",
    "birch_log",
    "birch_leaves",
    "snow_block",
    "missing",
];

struct Rng(u64);
impl Rng {
    fn new(key: &str) -> Self {
        // FNV-1a of the key: stable across platforms and versions.
        let mut h = 0xcbf2_9ce4_8422_2325u64;
        for b in key.bytes() {
            h = (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3);
        }
        Self(h | 1)
    }
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    /// Signed jitter in `-amount..=amount`.
    fn jitter(&mut self, amount: i32) -> i32 {
        (self.next() % (2 * amount as u64 + 1)) as i32 - amount
    }
}

fn shade(base: [u8; 3], delta: i32, alpha: u8) -> [u8; 4] {
    let c = |v: u8| (i32::from(v) + delta).clamp(0, 255) as u8;
    [c(base[0]), c(base[1]), c(base[2]), alpha]
}

/// Noise around a base color.
fn speckle(rng: &mut Rng, base: [u8; 3], amount: i32) -> Rgba8Image {
    let mut img = Rgba8Image::filled(FALLBACK_SIZE, FALLBACK_SIZE, [0; 4]);
    for y in 0..FALLBACK_SIZE {
        for x in 0..FALLBACK_SIZE {
            img.set(x, y, shade(base, rng.jitter(amount), 255));
        }
    }
    img
}

/// Ore: stone with clusters of a colored mineral.
fn ore(rng: &mut Rng, mineral: [u8; 3]) -> Rgba8Image {
    let mut img = speckle(rng, [125, 125, 125], 12);
    for _ in 0..5 {
        let (cx, cy) = (rng.next() % 14 + 1, rng.next() % 14 + 1);
        for (dx, dy) in [(0, 0), (1, 0), (0, 1), (1, 1)] {
            if rng.next() % 4 != 0 {
                let (x, y) = ((cx + dx) as u32, (cy + dy) as u32);
                img.set(x.min(15), y.min(15), shade(mineral, rng.jitter(15), 255));
            }
        }
    }
    img
}

/// Bark with vertical stripes.
fn log(rng: &mut Rng, base: [u8; 3]) -> Rgba8Image {
    let mut img = Rgba8Image::filled(FALLBACK_SIZE, FALLBACK_SIZE, [0; 4]);
    for y in 0..FALLBACK_SIZE {
        for x in 0..FALLBACK_SIZE {
            let stripe = if x % 4 == 0 { -25 } else { 0 };
            img.set(x, y, shade(base, stripe + rng.jitter(8), 255));
        }
    }
    img
}

/// Leaves with holes.
fn leaves(rng: &mut Rng, base: [u8; 3]) -> Rgba8Image {
    let mut img = Rgba8Image::filled(FALLBACK_SIZE, FALLBACK_SIZE, [0; 4]);
    for y in 0..FALLBACK_SIZE {
        for x in 0..FALLBACK_SIZE {
            if rng.next() % 5 != 0 {
                img.set(x, y, shade(base, rng.jitter(20), 255));
            }
        }
    }
    img
}

/// Generates the fallback texture for a key. Deterministic.
#[must_use]
pub fn fallback_texture(key: &str) -> Rgba8Image {
    let mut rng = Rng::new(key);
    let s = FALLBACK_SIZE;
    match key {
        "stone" => speckle(&mut rng, [125, 125, 125], 12),
        "dirt" => speckle(&mut rng, [134, 96, 67], 14),
        "sand" => speckle(&mut rng, [219, 207, 163], 8),
        "gravel" => speckle(&mut rng, [131, 127, 126], 30),
        "grass_block" => {
            let mut img = speckle(&mut rng, [134, 96, 67], 14);
            for y in 0..4 {
                for x in 0..s {
                    if y < 3 || rng.next() % 2 == 0 {
                        img.set(x, y, shade([95, 159, 53], rng.jitter(14), 255));
                    }
                }
            }
            img
        }
        "cobblestone" => {
            let mut img = speckle(&mut rng, [122, 122, 122], 10);
            for y in 0..s {
                for x in 0..s {
                    if (x + y * 3) % 7 == 0 || (x * 5 + y) % 11 == 0 {
                        img.set(x, y, shade([80, 80, 80], rng.jitter(8), 255));
                    }
                }
            }
            img
        }
        "oak_log" => {
            let mut img = Rgba8Image::filled(s, s, [0; 4]);
            for y in 0..s {
                for x in 0..s {
                    let stripe = if x % 4 == 0 { -25 } else { 0 };
                    img.set(x, y, shade([109, 85, 50], stripe + rng.jitter(8), 255));
                }
            }
            img
        }
        "oak_planks" => {
            let mut img = Rgba8Image::filled(s, s, [0; 4]);
            for y in 0..s {
                for x in 0..s {
                    let seam = if y % 4 == 3 || (x + (y / 4) * 5) % 16 == 0 {
                        -35
                    } else {
                        0
                    };
                    img.set(x, y, shade([162, 130, 78], seam + rng.jitter(6), 255));
                }
            }
            img
        }
        "spruce_log" => log(&mut rng, [70, 50, 30]),
        "spruce_leaves" => leaves(&mut rng, [40, 85, 45]),
        "birch_log" => {
            let mut img = speckle(&mut rng, [215, 212, 200], 8);
            for _ in 0..10 {
                let (x, y) = ((rng.next() % 14) as u32, (rng.next() % 16) as u32);
                img.set(x, y, [40, 40, 36, 255]);
                img.set(x + 1, y, [52, 50, 44, 255]);
            }
            img
        }
        "birch_leaves" => leaves(&mut rng, [104, 150, 60]),
        "snow_block" => speckle(&mut rng, [240, 246, 250], 5),
        "coal_ore" => ore(&mut rng, [40, 40, 40]),
        "iron_ore" => ore(&mut rng, [216, 175, 147]),
        "water" => {
            let mut img = Rgba8Image::filled(s, s, [0; 4]);
            for y in 0..s {
                for x in 0..s {
                    let wave = if (x + 2 * y) % 8 < 2 { 18 } else { 0 };
                    img.set(x, y, shade([47, 87, 196], wave + rng.jitter(6), 180));
                }
            }
            img
        }
        "oak_leaves" => {
            let mut img = Rgba8Image::filled(s, s, [0; 4]);
            for y in 0..s {
                for x in 0..s {
                    if rng.next() % 5 != 0 {
                        img.set(x, y, shade([59, 122, 39], rng.jitter(20), 255));
                    }
                }
            }
            img
        }
        "glass" => {
            let mut img = Rgba8Image::filled(s, s, [0; 4]);
            for i in 0..s {
                for (x, y) in [(i, 0), (i, s - 1), (0, i), (s - 1, i)] {
                    img.set(x, y, [200, 225, 230, 255]);
                }
            }
            for i in 3..7 {
                img.set(i, 9 - i, [235, 245, 250, 200]);
            }
            img
        }
        "torch" => {
            let mut img = Rgba8Image::filled(s, s, [0; 4]);
            for y in 6..s {
                img.set(7, y, [109, 85, 50, 255]);
                img.set(8, y, [92, 70, 40, 255]);
            }
            for (x, y) in [(7, 4), (8, 4), (7, 5), (8, 5)] {
                img.set(x, y, [255, 216, 80, 255]);
            }
            img
        }
        "glowstone" => {
            let mut img = speckle(&mut rng, [171, 131, 84], 15);
            for y in 0..s {
                for x in 0..s {
                    if rng.next() % 3 == 0 {
                        img.set(x, y, shade([255, 225, 140], rng.jitter(20), 255));
                    }
                }
            }
            img
        }
        _ => {
            let mut img = Rgba8Image::filled(s, s, [0; 4]);
            for y in 0..s {
                for x in 0..s {
                    let on = (x / 8 + y / 8) % 2 == 0;
                    img.set(
                        x,
                        y,
                        if on {
                            [248, 0, 248, 255]
                        } else {
                            [0, 0, 0, 255]
                        },
                    );
                }
            }
            img
        }
    }
}

/// The fallback key of a texture reference such as `core:fallback/stone` or a
/// block id like `core:stone`: the last path segment.
#[must_use]
pub fn fallback_key(reference: &str) -> &str {
    let path = reference.split_once(':').map_or(reference, |(_, p)| p);
    path.rsplit('/').next().unwrap_or(path)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn textures_are_deterministic_and_distinct() {
        for key in FALLBACK_KEYS {
            let a = fallback_texture(key);
            assert_eq!(a, fallback_texture(key), "{key}");
            assert_eq!((a.width(), a.height()), (16, 16));
        }
        assert_ne!(fallback_texture("stone"), fallback_texture("dirt"));
        assert_eq!(
            fallback_texture("no_such_block"),
            fallback_texture("missing")
        );
        assert!(
            fallback_texture("oak_leaves")
                .pixels()
                .iter()
                .any(|p| p[3] == 0)
        );
        assert!(
            fallback_texture("water")
                .pixels()
                .iter()
                .all(|p| p[3] == 180)
        );
    }

    #[test]
    fn keys_from_references() {
        assert_eq!(fallback_key("core:fallback/stone"), "stone");
        assert_eq!(fallback_key("core:oak_log"), "oak_log");
        assert_eq!(fallback_key("glass"), "glass");
    }
}
